def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 6 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    # Recolor zero objects to the color of another object with the same area.
    sizes_to_colors = {}
    for color, cells in comps:
        if color != 0:
            sizes_to_colors.setdefault(len(cells), color)

    for color, cells in comps:
        if color == 0 and len(cells) in sizes_to_colors:
            new_color = sizes_to_colors[len(cells)]
            for r, c in cells:
                out[r][c] = new_color

    return out
